import {texEq as eq,inlineMath} from './math.js';
import {section,table as baseTable,cite,topic,mountTopic,rangePlayback} from './topic-tools.js';
import {areaFrame} from './geometry-model.js';
export const geometrySections=[['magnitude','Magnitude, direction and inner product'],['normalization','Normalization keeps direction, not diversity'],['distance','Distance between unit embeddings'],['objectives','Norm, squared loss and penalty'],['convexity','Which uniqueness claim is valid?'],['ridge','Gaussian error and ridge precision'],['cross','Cross product: oriented area and normal'],['area-lab','Angle changes similarity and area differently'],['orientation','2D turns and 3D triangle normals'],['applications','Use the geometry that matches the task'],['sources','Sources and related owners']];
export const geometryMeta={slug:'math/geometry',title:'Vectors and Geometry',description:'Magnitude, unit embeddings, loss/penalty distinctions, dot versus cross products, orientation and the limits of normalization.',date:'2026-04-10',updated:'2026-10-06',topicPath:['math'],tags:['L2','norm','normalization','cosine','cross product','signed area','orientation','ridge','collapse'],prototype:true,visibility:'public',kind:'dense-topic',learningGoals:['Separate norm, distance, squared loss and parameter penalty','Interpret unit-vector distances without assuming noncollapse','Compute oriented area and normals with correct signs and degeneracies'],related:['training/objectives','models/position']};
export const geometryAliases=[];
const table=(caption,heads,rows)=>baseTable(caption,heads,rows).replace('class="dense-table-wrap"',`class="dense-table-wrap" tabindex="0" role="region" aria-label="${caption}"`).replace('<table>','<table style="min-width:580px">');
function areaSvg(f){const point=v=>[180+40*v[0],160-40*v[1]],o=[180,160],a=point(f.a),b=point(f.b),sum=point(f.a.map((v,i)=>v+f.b[i]));return `<path d="M30 160H470 M180 20V300" stroke="#53404f"/><polygon points="${o} ${a} ${sum} ${b}" fill="#88425866" stroke="#bd738e"/><line x1="${o[0]}" y1="${o[1]}" x2="${a[0]}" y2="${a[1]}" stroke="#bad6fa" stroke-width="5"/><circle cx="${a[0]}" cy="${a[1]}" r="6" fill="#bad6fa"/><line x1="${o[0]}" y1="${o[1]}" x2="${b[0]}" y2="${b[1]}" stroke="#bd738e" stroke-width="4" stroke-dasharray="8 4"/><circle cx="${b[0]}" cy="${b[1]}" r="6" fill="#bd738e"/>`;}
const areaLab=`<div id="area-lab" class="topic-scene" data-area-lab><h3>Alignment is not area</h3><p>Fixed lengths: |a|=2, |b|=3. Solid blue a points along +x. Dashed burgundy b changes its angle. Shading is the parallelogram they span.</p><label>Signed angle <output data-angle>45</output>°<input type="range" min="-180" max="180" step="1" value="45" aria-label="Vector signed angle"></label><svg viewBox="0 0 500 320" role="img" aria-label="Two planar vectors span a shaded parallelogram">${areaSvg(areaFrame(45))}</svg><div class="scene-stats"><span>Dot product <output data-dot>4.243</output></span><span>Signed z component <output data-signed>4.243</output></span><span>Area <output data-area>4.243</output></span><span>Cosine <output data-cosine>0.707</output></span></div><p data-area-caption>Positive orientation: the cross product points along +z.</p><div class="dense-actions"><button data-play type="button">Play</button><button data-reset type="button">Replay</button></div><p class="topic-scenes-caption">Exact planar toy with 3D cross-product interpretation. World scale stays fixed. Motion is an angle sweep, not training or a measured representation trajectory.</p></div>`;
export function geometryReader(link){return topic(geometryMeta,geometrySections,'Use length, angle and orientation for different questions.',`
<p>A vector has both magnitude and direction. A similarity score asks whether two directions align. A distance asks how far their coordinates differ. An oriented area asks which way one vector turns toward another.</p><p>These quantities are related, but not interchangeable. The distinction matters for embeddings, geometric algorithms and losses. It also prevents treating unit normalization as a complete training objective.</p>
${section('magnitude','Magnitude, direction and inner product',`${eq(String.raw`\begin{aligned}\lVert x\rVert_2&=\sqrt{\sum_i x_i^2}\\a\cdot b&=\sum_i a_ib_i=\lVert a\rVert_2\lVert b\rVert_2\cos\theta\end{aligned}`,'The angle needs two nonzero vectors. The Euclidean norm is their distance from the origin.')}
<p>The vector [3,4] has norm 5. Its direction is [3/5,4/5]. An orthogonal rotation changes coordinates but preserves the norm and dot product. This symmetry suits Euclidean geometry; it does not imply that a learned embedding distribution is isotropic.</p><p>The L1 norm sums absolute coordinates. In two dimensions, its unit ball is a diamond; the L2 unit ball is a circle. Those constraint shapes affect optimization, but the shape alone is not a guarantee of robustness or sparsity for every objective.</p>`)}
${section('normalization','Normalization keeps direction, not diversity',`${eq(String.raw`u=\frac{x}{\lVert x\rVert_2},\quad x\ne0\ \Longrightarrow\ \lVert u\rVert_2=1`,'The zero vector has no defined direction. State the zero/near-zero policy in an implementation.')}
<p>Normalization removes radial scale. All positive multiples of x become the same u. It is not centering or whitening, and it does not remove statistical dependencies between embedding dimensions.</p><p>If every sample maps to [1,0], every embedding has unit norm but the representation has collapsed. Normalization constrains radius, not the diversity of directions. A useful self-supervised objective needs another mechanism to preserve informative variation.</p><p>The original LeJEPA/FaceNet examples motivate bounded embedding geometry, not a proof that normalization alone prevents collapse. Inspect the actual objective, architecture and regularizer. <a href="${link('models/vision')+'#gaussian-target'}">SIGReg reference →</a> addresses distributional constraints rather than only radius.</p><p>Dividing by max(‖x‖,ε) bounds amplification near zero, but outputs with ‖x‖&lt;ε are not unit vectors. Adding ε inside a norm also changes the map. Do not silently claim exact normalization for those policies.</p>`)}
${section('distance','Distance between unit embeddings',`${eq(String.raw`\begin{aligned}u\cdot v&=\cos\theta\\\lVert u-v\rVert_2^2&=\lVert u\rVert_2^2+\lVert v\rVert_2^2-2u\cdot v\\&=2-2\cos\theta\end{aligned}`,'Both u and v must have unit norm. Their squared distance lies in [0,4].')}${table('Three reference directions',['Relation','Cosine','Squared distance','Distance'],[['Same direction','1','0','0'],['Orthogonal','0','2',inlineMath(String.raw`\sqrt2`)],['Opposite direction','−1','4','2']])}<p>Cosine ranking and Euclidean-distance ranking agree for exactly normalized embeddings. They need not agree when vector magnitudes vary. A high dot product can then reflect large norms rather than closer directions.</p><p>Even on a sphere, geometric closeness is only as semantically useful as the learned representation. Unit norm does not establish meaningful neighbors.</p>`)}
${section('objectives','Norm, squared loss and penalty',`${table('Specify the formula instead of only saying L2',['Quantity','Formula','Question'],[['Magnitude',inlineMath(String.raw`\lVert x\rVert_2`),'How long is one vector?'],['Distance',inlineMath(String.raw`\lVert\hat y-y\rVert_2`),'How far is a prediction from its target?'],['Squared error sum',inlineMath(String.raw`\sum_i(\hat y_i-y_i)^2`),'How much squared prediction error?'],['Mean squared error',inlineMath(String.raw`\frac1n\sum_i(\hat y_i-y_i)^2`),'Average error under a specified reduction'],['Squared parameter penalty',inlineMath(String.raw`\lambda\lVert w\rVert_2^2`),'How large are model parameters?']])}
<p>Norm and squared norm have different derivatives. For a nonzero vector, ${inlineMath(String.raw`\nabla\lVert x\rVert_2=\frac{x}{\lVert x\rVert_2}`)}. The norm is not differentiable at zero. By contrast, ${inlineMath(String.raw`\nabla\lVert x\rVert_2^2=2x`)} everywhere. The common smooth L2 penalty uses the squared norm.</p><p>Squared residuals weight large errors more than absolute residuals. MSE therefore has different outlier sensitivity from MAE. Nonsmooth L1 objectives are not automatically unstable; subgradient and proximal methods can optimize them well.</p><p>L1 penalties can produce exact zero coefficients in appropriate regularized models. Squared L2 penalties usually shrink continuously rather than select exact zeros. This is a penalty effect, not a universal statement about L1 distances between data points.</p><p><a href="${link('training/objectives')}">Losses and Objectives →</a> owns estimator choice, probability scoring, margins and reduction. Geometry supplies the quantities those objectives use.</p>`)}
${section('convexity','Which uniqueness claim is valid?',`<p>The Euclidean unit ball is strictly convex, but the norm function is not strictly convex along positive rays. For a nonzero x, the midpoint norm ${inlineMath(String.raw`\left\lVert\frac{x+2x}{2}\right\rVert_2`)} equals the average norm ${inlineMath(String.raw`\frac{\lVert x\rVert_2+\lVert2x\rVert_2}{2}`)}. Therefore “L2 always gives one optimum” is not a valid claim.</p><p>The squared Euclidean norm is strictly convex in its own vector argument. The objective ${inlineMath(String.raw`\lVert Aw-y\rVert_2^2`)} is strictly convex in w only when A has full column rank. If A has a nullspace, multiple weights can give the same prediction.</p><p>Adding ${inlineMath(String.raw`\lambda\lVert w\rVert_2^2`)} with λ&gt;0 makes this fully penalized linear least-squares problem strictly convex. A neural network's nonlinear parameterization remains a different optimization problem. A positive penalty does not make arbitrary neural training globally convex.</p>`)}
${section('ridge','Gaussian error and ridge precision',`${eq(String.raw`\begin{aligned}-\log p(y\mid\mu,\Sigma)&=\tfrac12(y-\mu)^\top\Sigma^{-1}(y-\mu)\\&\quad+\tfrac12\log\det\Sigma+\tfrac n2\log(2\pi)\end{aligned}`,`For y, μ in ℝⁿ and positive-definite Σ. With fixed ${inlineMath(String.raw`\Sigma=\sigma^2 I`)}, optimizing μ is equivalent to minimizing squared Euclidean residuals. A learned or anisotropic covariance changes the objective.`)}
<p>Squared error's Gaussian connection is conditional, not an identity with all likelihoods. If σ also changes, its scale and log-normalization term matter. Negative log density is not the numerical reciprocal of a probability.</p>${eq(String.raw`\begin{aligned}\min_w\;&\lVert Xw-y\rVert_2^2+\lambda\lVert w\rVert_2^2\\(X^\top X+\lambda I)w&=X^\top y\end{aligned}`,'Solve the linear system. The displayed λ assumes a sum-of-squares objective; a mean reduction changes its scaling.')}
<p>Ridge adds λI to the feature Gram matrix, not indiscriminately to any covariance before inversion. A Gaussian parameter prior gives a quadratic penalty with its precision matrix. That precision is inverse prior covariance.</p><p>“Inverse loss” is not a standard replacement name for L2. Nor is L2 the dual of L1: the dual norm of L1 is L∞, while L2 is self-dual. Use the exact likelihood, prior and penalty definitions rather than that ambiguous label.</p>`)}
${section('cross','Cross product: oriented area and normal',`${eq(String.raw`\begin{aligned}a\times b&=\begin{bmatrix}a_2b_3-a_3b_2\\a_3b_1-a_1b_3\\a_1b_2-a_2b_1\end{bmatrix}\\\lVert a\times b\rVert_2&=\lVert a\rVert_2\lVert b\rVert_2\sin\theta,\quad0\le\theta\le\pi\end{aligned}`,'The usual cross product here acts on 3D vectors. It is perpendicular to both inputs; its magnitude is parallelogram area.')}
<p>The right-hand rule fixes direction: curl from a toward b and the thumb gives a×b. Swapping inputs reverses it. For unit x and y axes, [1,0,0]×[0,1,0]=[0,0,1].</p><p>The determinant mnemonic has unit vectors i,j,k in its first row and components of a,b below. Expand it to obtain the component formula. The middle component includes the determinant's alternating sign.</p>${table('Algebraic checks',['Property','Identity'],[['Anticommutative',inlineMath(String.raw`a\times b=-(b\times a)`)],['Distributive',inlineMath(String.raw`a\times(b+c)=a\times b+a\times c`)],['Scalar compatibility',inlineMath(String.raw`(ka)\times b=k(a\times b)=a\times(kb)`)],['Self product',inlineMath(String.raw`a\times a=0`)]])}<p>Parallel or antiparallel nonzero vectors give zero. A zero input also gives zero. In these cases no unique unit normal exists. Dot product zero tests orthogonality; cross product zero tests collinearity or a zero input.</p>${areaLab}`)}
${section('orientation','2D turns and 3D triangle normals',`${eq(String.raw`\begin{aligned}\operatorname{orient}(A,B,C)&=(B_x-A_x)(C_y-A_y)\\&\quad-(B_y-A_y)(C_x-A_x)\end{aligned}`,'With x right and y up: positive means counterclockwise, negative clockwise, zero collinear. Screen coordinates often invert y.')}
<p>This scalar is the z component of the cross product after embedding the two edge vectors in the xy plane. Its absolute value is twice the triangle area. The sign is useful for turn tests; the magnitude is not an angle.</p><pre><code>u, v = B - A, C - A
normal = cross(u, v)
triangle_area = norm(normal) / 2
if norm(normal) &gt; tolerance:
    unit_normal = normal / norm(normal)
# Otherwise the triangle is degenerate at the chosen precision.</code></pre><p>Floating-point cancellation can make nearly collinear predicates unreliable. A tolerance depends on coordinate scale and application. Robust computational geometry may need adaptive or exact predicates instead of one arbitrary epsilon.</p>`)}
${section('applications','Use the geometry that matches the task',`<p>Graphics uses triangle normals for shading; reversing vertex order reverses the normal. Physics uses r×F for torque and r×p for angular momentum. Geometry algorithms use signed turns to track orientation.</p><p>High-dimensional embeddings usually need dot products, norms or distances, not a direct 3D cross product. Projecting them to three coordinates can make a diagram readable, but orthogonality in that projection does not prove orthogonality in the original space.</p><p>For embeddings, state whether magnitude carries information before normalizing. For losses, state sum versus mean and squared versus unsquared. For geometry, state axis orientation, coordinate scale and degeneracy policy. These small contracts determine whether the same formula answers the intended question.</p>`)}
${section('sources','Sources and related owners',`<p>${cite('https://mathinsight.org/cross_product','Cross-product geometry')} · ${cite('https://web.stanford.edu/class/stats305b/notes/Ridge.html','Ridge and Gaussian-prior precision')}</p><div class="dense-related"><a href="${link('training/objectives')}">Losses and Objectives →</a><a href="${link('models/position')}">Rotations and positional geometry →</a><a href="${link('models/vision')+'#gaussian-target'}">Self-supervised vision →</a></div>`)}
`);}
geometryMeta.searchText=geometryReader(()=> '').replace(/<[^>]*>/g,' ');
export function mountGeometry(scope=document){mountTopic(scope,geometryMeta.slug,article=>{const lab=article.querySelector('[data-area-lab]');rangePlayback(article,lab,angle=>{const f=areaFrame(angle);lab.querySelector('svg').innerHTML=areaSvg(f);lab.querySelector('[data-angle]').textContent=angle;for(const [key,value]of [['dot',f.dot],['signed',f.signed],['area',f.area],['cosine',f.cosine]])lab.querySelector(`[data-${key}]`).textContent=value.toFixed(3);lab.querySelector('[data-area-caption]').textContent=Math.abs(f.signed)<1e-10?'Collinear: area is zero to numerical precision; no unique unit normal.':f.signed>0?'Positive orientation: the cross product points along +z.':'Negative orientation: the cross product points along −z. Area is still nonnegative.';},16000);});}
